// Module 17 evidence: one real appliance installed from a package generated by the dev stack; the local
// administrator's "Delete all data and deregister" page, the confirmation, the progress, the final page; the
// dashboard afterwards (deployment gone, the audit event in Activity & audit logs and on the client's activity
// tab). Writes deletion-sample.json (counts and phases, never secrets). Removes the appliance with the package's
// own uninstall script, without --force.
// Usage: node scripts/screenshots-m17.mjs
import { spawn, spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from '@playwright/test';

const base = process.env.BASE_URL ?? 'http://localhost:3210';
const outDir = fileURLToPath(new URL('../../../docs/reports/module-17/', import.meta.url));
const shots = `${outDir}screenshots/`;
mkdirSync(shots, { recursive: true });
const env = Object.fromEntries(readFileSync(new URL('../../api/.env', import.meta.url), 'utf8').split(/\r?\n/).filter((l) => /^[A-Z0-9_]+=/.test(l)).map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]));
const sh = (cmd, timeout = 400_000) => {
  const r = spawnSync('wsl', ['--exec', 'bash', '-c', cmd], { encoding: 'utf8', timeout });
  return { code: r.status, out: (r.stdout ?? '').trim(), err: (r.stderr ?? '').trim() };
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const hostIp = sh(`ip -4 route get 1.1.1.1 | awk '{for(i=1;i<=NF;i++) if($i=="src") print $(i+1)}'`).out;

const API_KEY = `demo-${Math.random().toString(36).slice(2, 10)}`;
const caPath = join(realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m17ca-'))), 'ca.pem');
const fake = spawn(process.execPath, [fileURLToPath(new URL('./fake-psa.mjs', import.meta.url)), hostIp, API_KEY, caPath], { stdio: ['ignore', 'pipe', 'inherit'] });
const port = await new Promise((resolve, reject) => {
  fake.stdout.on('data', (d) => { for (const line of String(d).split(/\r?\n/)) { const m = /^PORT (\d+)$/.exec(line); if (m) resolve(Number(m[1])); } });
  fake.on('exit', (code) => reject(new Error(`fake PSA exited with ${code}`)));
});

const browser = await chromium.launch({ channel: 'msedge' });
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();
const login = await page.request.post(`${base}/api/v1/auth/login`, { data: { email: 'avery.admin@psacc.test', password: env.SEED_DEFAULT_PASSWORD }, headers: { origin: base } });
if (login.status() !== 200) throw new Error(`login ${login.status()}`);
const csrf = async () => ({ origin: base, 'x-csrf-token': (await ctx.cookies()).find((c) => c.name === 'psacc_csrf').value });
const api = async (method, path, data) => {
  const r = await page.request.fetch(`${base}/api/v1${path}`, { method, data, headers: await csrf() });
  if (!r.ok()) throw new Error(`${method} ${path} → ${r.status()} ${await r.text()}`);
  return (r.headers()['content-type'] ?? '').includes('json') ? r.json() : r.body();
};
const shot = async (p, name, full = true, focus = null) => {
  await p.evaluate(() => window.scrollTo(0, 0));
  if (focus) await p.locator(focus).first().scrollIntoViewIfNeeded();
  await p.addStyleTag({ content: 'nextjs-portal { display: none !important; }' }).catch(() => undefined);
  await p.waitForTimeout(400);
  await p.screenshot({ path: `${shots}${name}.png`, fullPage: full });
  console.log('saved', name);
};
const waitFor = async (fn, ms, label) => { const end = Date.now() + ms; while (Date.now() < end) { if (await fn()) return; await sleep(2000); } throw new Error(`timed out: ${label}`); };

const client = (await api('GET', '/clients?status=active&pageSize=50')).items.find((c) => c.code !== 'CL-00001');
const services = await api('GET', `/clients/${client.id}/services`);
const instance = await api('POST', '/psa-instances', {
  clientId: client.id, providerKey: 'custom_rest', displayName: `${client.displayName} — Demo PSA ${Date.now().toString(36)}`, authMethod: 'api_key',
  config: { baseUrl: `https://${hostIp}:${port}/api`, healthPath: '/health', apiKeyHeader: 'X-API-Key', ticketsPath: '/tickets' }, enabledServiceIds: services.filter((s) => s.requiresPsa).map((s) => s.id),
});
const today = new Date().toISOString().slice(0, 10);
const demoLicense = await api('POST', '/licenses', { clientId: client.id, displayName: 'Help Desk Plus (demo)', startsAt: today, endsAt: null, maxDeployments: 2, notes: 'Created for the Module 17 walkthrough.' });
const dep = await api('POST', '/deployments', { clientId: client.id, psaInstanceId: instance.id, licenseId: demoLicense.id, targetEnvironment: 'local_test', targetOs: 'linux', targetArch: 'amd64', hostLabel: 'module17-demo' });
const pkg = (await api('POST', `/deployments/${dep.id}/packages`, { tokenValidityHours: 4 })).currentPackage;
const zip = await api('POST', `/deployments/${dep.id}/packages/${pkg.id}/download`);
const winTmp = realpathSync.native(mkdtempSync(join(tmpdir(), 'psacc-m17-')));
writeFileSync(join(winTmp, pkg.fileName), zip);
const project = `psacc-${dep.code.toLowerCase()}`;
const work = `/tmp/psacc-m17shots/${project}`;
const adminPort = 18000 + (Number(dep.code.replace(/\D/g, '')) % 1000);
const unix = (p) => sh(`wslpath -a '${p}'`).out;
const adminBase = `http://127.0.0.1:${adminPort}`;
const curl = (args) => sh(`curl -s -o /tmp/psacc-m17shots/body -w '%{http_code}' -b /tmp/psacc-m17shots/jar -c /tmp/psacc-m17shots/jar ${args}; echo; cat /tmp/psacc-m17shots/body`, 60_000).out;
const agentState = () => { const r = sh(`cd ${work} && docker compose -f compose.yaml exec -T edge-agent edge-agent status`, 60_000); try { return JSON.parse(r.out); } catch { return {}; } };
const sample = { deployment: dep.code, client: client.code, license: demoLicense.code, steps: [] };
let wiped = false;

try {
  let r = sh(`rm -rf /tmp/psacc-m17shots && mkdir -p /tmp/psacc-m17shots && cd /tmp/psacc-m17shots && unzip -q "${unix(join(winTmp, pkg.fileName))}" && cd ${project} && cp config/edge.env.template .env && scripts/install.sh`);
  if (r.code !== 0) throw new Error(`install failed: ${r.err || r.out}`);
  await waitFor(async () => (await api('GET', `/deployments/${dep.id}`)).lifecycleState === 'verified', 180_000, 'verified');
  const pw = `demo-${dep.code}-local-admin-pass`;
  curl(`-X POST --data-urlencode username=localadmin --data-urlencode password=${pw} --data-urlencode confirm=${pw} ${adminBase}/setup`);
  const token = /name="csrf" value="([^"]+)"/.exec(curl(`${adminBase}/credentials`))[1];
  curl(`-X POST --data-urlencode csrf=${token} --data-urlencode field_apiKey=${API_KEY} --data-urlencode "field_tlsCaCertificate@${unix(caPath)}" ${adminBase}/credentials`);
  if (!curl(`-X POST --data-urlencode csrf=${token} ${adminBase}/credentials/test`).includes('Connection verified')) throw new Error('the appliance test did not verify');
  await waitFor(async () => (await api('GET', `/deployments/${dep.id}`)).applianceLicense?.state === 'valid', 90_000, 'verdict reported');
  sample.steps.push({ step: 'installed', lifecycle: (await api('GET', `/deployments/${dep.id}`)).lifecycleState, agentState: agentState().state });

  // 1. The dashboard before: the deployment exists.
  await page.goto(`${base}/deployments/${dep.id}`, { waitUntil: 'networkidle' });
  await shot(page, '01-overview-before-deletion', false);
  // 2. The appliance: the deletion page and the confirmation.
  const edge = await browser.newContext({ viewport: { width: 1200, height: 900 }, deviceScaleFactor: 2 });
  const ep = await edge.newPage();
  await ep.goto(`http://localhost:${adminPort}/login`);
  await ep.getByLabel('User name').fill('localadmin');
  await ep.getByLabel('Password').fill(pw);
  await ep.getByRole('button', { name: 'Sign in' }).click();
  await ep.goto(`http://localhost:${adminPort}/deletion`, { waitUntil: 'networkidle' });
  await ep.getByTestId('deletion-form').waitFor();
  await shot(ep, '02-appliance-deletion-page', true);
  await ep.getByLabel('Reason (optional, shared with the provider\'s audit trail)').fill('Moving to another provider');
  await ep.getByLabel(`Type the deployment ID ${dep.code}`).fill('DEP-00000');
  await ep.getByLabel('Your password').fill(pw);
  await ep.getByText('I understand that all tickets').click();
  await ep.getByTestId('deletion-submit').click();
  await ep.getByText(`Type the deployment ID ${dep.code} exactly to confirm.`).waitFor();
  await shot(ep, '03-appliance-deletion-wrong-id', false);
  await ep.getByLabel(`Type the deployment ID ${dep.code}`).fill(dep.code);
  await ep.getByLabel('Your password').fill(pw);
  await ep.getByText('I understand that all tickets').click();
  await ep.getByTestId('deletion-submit').click();
  await ep.getByTestId('deletion-phase').waitFor();
  await shot(ep, '04-appliance-deletion-in-progress', false);
  // 3. The appliance finishes; the final page.
  await waitFor(async () => agentState().state === 'deleted', 180_000, 'appliance deleted everything');
  wiped = true;
  const st = agentState();
  sample.steps.push({ step: 'deleted', agentState: st.state, deletion: { ...st.deletion, auditEventId: st.deletion?.auditEventId ? 'present' : null } });
  await ep.goto(`http://localhost:${adminPort}/deletion`, { waitUntil: 'networkidle' });
  await ep.getByTestId('deletion-done').waitFor();
  await shot(ep, '05-appliance-deletion-done', true);
  await ep.goto(`http://localhost:${adminPort}/tickets`, { waitUntil: 'networkidle' });
  await shot(ep, '06-appliance-locked-to-deletion-page', false);
  await edge.close();
  // 4. The dashboard afterwards: gone, and the audit event.
  const detail = await page.request.get(`${base}/api/v1/deployments/${dep.id}`);
  sample.steps.push({ step: 'control-plane', detailStatus: detail.status() });
  await page.goto(`${base}/deployments/${dep.id}`, { waitUntil: 'networkidle' });
  await shot(page, '07-dashboard-deployment-gone', false);
  await page.goto(`${base}/audit?q=${encodeURIComponent(dep.code)}&action=deployment.deleted_by_client`, { waitUntil: 'networkidle' });
  await page.getByText('deployment.deleted_by_client').first().waitFor();
  await shot(page, '08-audit-deleted-by-client', false);
  await page.goto(`${base}/clients/${client.id}/activity`, { waitUntil: 'networkidle' });
  await shot(page, '09-client-activity', false, 'text=deployment.deleted_by_client');
  const ev = (await api('GET', `/audit-events?action=deployment.deleted_by_client&pageSize=20`)).items.find((e) => e.targetDisplay === dep.code);
  sample.steps.push({ step: 'audit', found: !!ev, metadata: ev ? { code: ev.metadata.code, requestedBy: ev.metadata.requestedBy, reason: ev.metadata.reason, deleted: ev.metadata.deleted, lifecycleState: ev.metadata.lifecycleState } : null });
  // 5. Host side: the package's own wipe, without --force.
  r = sh(`cd ${work} && scripts/uninstall.sh --wipe --confirm ${dep.code}`, 300_000);
  sample.steps.push({ step: 'uninstall-wipe', exit: r.code, tail: r.out.split('\n').slice(-3) });
  if (r.code !== 0) throw new Error(`uninstall --wipe failed: ${r.err || r.out}`);
  sample.steps.push({ step: 'leftovers', containers: Number(sh(`docker ps -a --format '{{.Names}}' | grep -c '^${project}-' || true`).out), volumes: Number(sh(`docker volume ls -q | grep -c '^${project}_' || true`).out) });
  writeFileSync(`${outDir}deletion-sample.json`, JSON.stringify(sample, null, 2));
} catch (err) {
  // Diagnostics before the teardown: the appliance's own view of what happened.
  console.error(String(err));
  console.error(sh(`cd ${work} 2>/dev/null && docker compose -f compose.yaml logs --tail 60 edge-agent edge-worker edge-api 2>&1`, 60_000).out.slice(-6000));
  console.error(JSON.stringify(agentState().deletion ?? null));
  throw err;
} finally {
  sh(`cd ${work} 2>/dev/null && docker compose -f compose.yaml down --volumes --remove-orphans; rm -rf /tmp/psacc-m17shots`);
  rmSync(winTmp, { recursive: true, force: true });
  fake.kill('SIGTERM');
  rmSync(caPath, { force: true });
  await browser.close();
}
